function memoize(fn) {
  const cache = new Map()
  return (n) => {
    if (cache.has(n)) return cache.get(n)
    const r = fn(n)
    cache.set(n, r)
    return r
  }
}
let calls = 0
const square = memoize((n) => { calls++; return n * n })
square(2); square(3); square(2); square(3); square(2)
